import { useEffect, useState } from "react";
import "../styles/Bananas.css";

const NUM_BANANAS = 12;

function Bananas() {
  const [bananas, setBananas] = useState([]);

  useEffect(() => {
    const generated = Array.from({ length: NUM_BANANAS }, (_, i) => ({
      id: i,
      side: i % 2 === 0 ? "left" : "right",
      delay: Math.random() * 5, // delay in seconds
      duration: 4 + Math.random() * 4, // between 4s and 8s
      spinDirection: Math.random() > 0.5 ? "normal" : "reverse",
      offset: Math.random() * 20, // % from side
    }));
    setBananas(generated);
  }, []);

  return (
    <>
      {bananas.map((banana) => (
        <img
          key={banana.id}
          src="/banana.png" // Place banana.png in your public/ folder
          alt="banana"
          className="banana"
          style={{
            animationDelay: `${banana.delay}s`,
            animationDuration: `${banana.duration}s`,
            animationDirection: banana.spinDirection,
            [banana.side]: `${banana.offset}%`,
          }}
        />
      ))}
    </>
  );
}

export default Bananas;
